-- 222: Original BrillaPrep WASSCE BrillaPrep transitional Sculpture beta content blueprint questions, part 10.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_222_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_222_guard;
INSERT INTO _migration_222_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_037' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_8' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How is the direct cost of casting material estimated for a sculpture edition?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Cost one measured cast and add a waste allowance, but use that figure for the whole edition without multiplying by edition size","B. Multiply measured material per cast by unit cost and the planned number of casts, then allow for justified waste","C. Multiply the price of one supplier pack by the number of casts, even when each pack yields material for several casts","D. Divide the total measured material by its unit price, then add the waste percentage as a currency amount"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A defensible estimate connects measured consumption, supplier price and edition quantity. Documented waste, labour, mould cost and shared overhead can then be added separately and transparently. Therefore the correct answer is B: Multiply measured material per cast by unit cost and the planned number of casts, then allow for justified waste.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_8' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_037' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_222_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_038' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_8' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of a condition report before moving or conserving a sculpture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Record existing materials, cracks, losses, repairs and surface changes with dated images","B. Replace material identification with an estimated sale price","C. Authorise cleaning as soon as dust appears on the surface","D. Assign blame for every mark before the object has been examined"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A dated written and photographic baseline distinguishes existing features from later damage. It supports packing, handling, treatment planning and accountability appropriate to the object’s materials. Therefore the correct answer is A: Record existing materials, cracks, losses, repairs and surface changes with dated images.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_038' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_222_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_039' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_8' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which storage practice best protects a fragile mixed-media sculpture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Rest the work on its broadest visible plane over uniform foam, assuming the largest area is also the strongest support","B. Support strong load-bearing points in a stable environment and provide a clear handling plan","C. Seal the complete work tightly in polyethylene with desiccant so one enclosure can control every component material","D. Detach projecting parts for compact storage even when their joints were not designed for repeated assembly"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Conservation storage considers load paths, abrasion, dust, light, humidity, temperature and access. Packaging and handling should not introduce new structural or surface risks. Therefore the correct answer is B: Support strong load-bearing points in a stable environment and provide a clear handling plan.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_039' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_222_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_040' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_8' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which portfolio evidence most convincingly demonstrates original sculptural development?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A sequence of undated process photographs without captions because the visible changes are expected to explain each decision","B. Dated sketches, maquette trials, process images, decisions and critical evaluation linked to the final work","C. Final photographs and a retrospective artist statement that describes the process only after completion","D. Referenced artist images and technical notes without maquette trials or evidence of revisions to the student’s own work"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Authentic process evidence connects idea, research, experiments, revisions and outcome. Captions and reflection make the maker’s decisions, technical learning and authorship visible to a reviewer. Therefore the correct answer is B: Dated sketches, maquette trials, process images, decisions and critical evaluation linked to the final work.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_040' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_037', 'topic_was_sculpture_b004_8', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'How is the direct cost of casting material estimated for a sculpture edition?', 'multiple_choice', NULL, '["A. Cost one measured cast and add a waste allowance, but use that figure for the whole edition without multiplying by edition size","B. Multiply measured material per cast by unit cost and the planned number of casts, then allow for justified waste","C. Multiply the price of one supplier pack by the number of casts, even when each pack yields material for several casts","D. Divide the total measured material by its unit price, then add the waste percentage as a currency amount"]', 'B', 'A defensible estimate connects measured consumption, supplier price and edition quantity. Documented waste, labour, mould cost and shared overhead can then be added separately and transparently. Therefore the correct answer is B: Multiply measured material per cast by unit cost and the planned number of casts, then allow for justified waste.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_8', 'Explain', 'AO1', NULL, NULL, 'board_waec');
