INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_sculpture_b004_037', 'q_was_sculpture_b004_038', 'q_was_sculpture_b004_039', 'q_was_sculpture_b004_040');
